steps.action:
curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -d '{
    "query": "query {
      teams {
        nodes {
          id
          name
          issues(filter: { priority: { _eq: 2 }, state: { name: { _contains: "Bug" } } }) {
            nodes {
              id
              identifier
              title
              priority
              assignee {
                name
              }
              state {
                name
              }
            }
          }
        }
      }
    }"
  }'
